def parse_mem_size(s):
    orig = s
    stripped_leading = s.lstrip(' \t\n\v\f\r')
    num_re = re.compile(r'^[+-]?(?:0[xX][0-9a-fA-F]+|0[xX][0-9a-fA-F]*\.[0-9a-fA-F]+(?:[pP][+-]?[0-9]+)?|0[xX][0-9a-fA-F]+\.[0-9a-fA-F]*(?:[pP][+-]?[0-9]+)?|(?:[0-9]+\.?[0-9]*|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|[iI][nN][fF](?:[iI][nN][iI][tT][yY])?|[nN][aA][nN])')
    m = num_re.match(stripped_leading)
    if not m:
        return (False, 0, orig)
    num_str = m.group(0)
    suffix = stripped_leading[len(num_str):]
    try:
        low = num_str.strip().lower()
        if low.startswith('+0x') or low.startswith('-0x') or low.startswith('0x'):
            sign = 1
            ns = num_str.strip()
            if ns[0] == '+':
                ns = ns[1:]
            elif ns[0] == '-':
                sign = -1
                ns = ns[1:]
            val = int(ns, 16) * sign
            val = float(val)
        elif low in ('inf','+inf','-inf','infinity','+infinity','-infinity'):
            val = float('-inf') if low.startswith('-') else float('inf')
        elif low in ('nan','+nan','-nan'):
            val = float('nan')
        else:
            val = float(num_str)
    except:
        val = 0.0
    if suffix == "":
        return (True, val, "")
    c0 = suffix[0]
    if c0 == 'k' or c0 == 'K':
        return (True, val*1024, "")
    elif c0 == 'M':
        return (True, val*1024*1024, "")
    elif c0 == 'G':
        return (True, val*1024*1024*1024, "")
    else:
        return (False, 0, suffix)

