# ================= JS ENGINE =================
# Value representation:
#  undefined -> Undefined singleton
#  null -> None (python None)  -- careful: None is null
#  boolean -> Python bool (True/False)
#  number -> Python float (always float, even for ints)
#  string -> Python str
#  bigint -> JSBigInt
#  symbol -> JSSymbol
#  object -> JSObject and subclasses

class UndefinedType:
    def __repr__(self): return "undefined"
    def __str__(self): return "undefined"
undefined = UndefinedType()
UNDEFINED = undefined

class JSBigInt:
    def __init__(self, v): self.value = int(v)
    def __repr__(self): return f"{self.value}n"
    def __eq__(self, o): return isinstance(o, JSBigInt) and self.value==o.value
    def __hash__(self): return hash(self.value)

class JSSymbol:
    _cnt = 0
    def __init__(self, desc=""):
        self.desc = desc if isinstance(desc, str) else ""
        JSSymbol._cnt += 1
        self.id = JSSymbol._cnt
    def __repr__(self): return f"Symbol({self.desc!r})"

class JSRefError(Exception): pass
class JSTypeError(Exception): pass
class JSSyntaxError(Exception): pass

# JS throw exception (for throw statement / runtime errors)
class JSThrow(Exception):
    def __init__(self, value):
        self.value = value

class JSReturn(Exception):
    def __init__(self, value):
        self.value = value

class JSBreak(Exception):
    def __init__(self, label=None):
        self.label = label

class JSContinue(Exception):
    def __init__(self, label=None):
        self.label = label

# For stack traces: track call stack
_call_stack = []  # list of (func_name, filename, line, col)

def is_undefined(v): return v is UNDEFINED
def is_null(v): return v is None
def is_bool(v): return type(v) is bool
def is_number(v): return type(v) is float
def is_string(v): return type(v) is str
def is_bigint(v): return isinstance(v, JSBigInt)
def is_symbol(v): return isinstance(v, JSSymbol)
def is_object(v): return isinstance(v, JSObject)

def js_typeof(v):
    if v is UNDEFINED: return "undefined"
    if v is None: return "object"
    if type(v) is bool: return "boolean"
    if type(v) is float: return "number"
    if type(v) is str: return "string"
    if isinstance(v, JSBigInt): return "bigint"
    if isinstance(v, JSSymbol): return "symbol"
    if isinstance(v, JSObject):
        if isinstance(v, JSFunction) and v.is_function_star_constr is False:
            pass
        return v.js_typeof_val if hasattr(v, 'js_typeof_val') else "object"
    return "object"

# Number formatting: JS ToString for numbers
def js_number_to_string(n):
    # n is float
    if math.isnan(n):
        return "NaN"
    if math.isinf(n):
        return "Infinity" if n>0 else "-Infinity"
    if n == 0.0:
        # String(-0) is "0", but preserve -0 for console? console uses inspect which shows -0
        # This function is for ToString (String(-0) -> "0")
        return "0"
    # Use repr with JS rules: need to match JS output
    # JS uses shortest round-trip, with e notation for large/small
    # Python repr is similar but not identical (e.g., Python uses e+XX, JS also e+XX? For 1e21, both "1e+21")
    # For integers, JS shows without decimal
    # We'll use Python repr and adjust
    # First, check if integer-valued and within safe range?
    # JS: (1).toString() -> "1", (1.5).toString() -> "1.5", (1e21).toString() -> "1e+21"
    # Python: repr(1.0) -> "1.0" (with .0), need to strip
    # Use: if n is integer-valued, format as int if within 1e21? Actually JS switches to exponential at 1e21
    # Let's implement JS number to string via algorithm:
    # If abs(n) >= 1e21 or (abs(n) < 1e-6 and n != 0): use exponential
    # Else use fixed
    # For exponential, JS uses e.g., "1e+21", "1.5e-7"
    # Python's repr for 1e21 is "1e+21" (same), for 1.5e-7 is "1.5e-07" (JS is "1.5e-7" without leading zero). Need to fix.
    # For fixed, JS uses decimal without trailing zeros, e.g., 0.30000000000000004 stays, 1.0 -> "1"
    # Python repr(0.30000000000000004) -> "0.30000000000000004" (same), repr(1.0) -> "1.0" (need "1")
    # We'll implement:
    if n == int(n) and abs(n) < 1e21:
        # integer-like
        # Use int conversion (careful for large)
        try:
            iv = int(n)
            # check round-trip: float(iv)==n ?
            if float(iv) == n:
                return str(iv)
        except:
            pass
    # For non-integers or large, use repr and fix
    s = repr(n)
